    SELECT a.id aid, s.id bid, c.id cid FROM a
    JOIN (SELECT id, k, y FROM b WHERE x != o.x) s ON s.k = a.x
    LEFT JOIN c ON c.y = s.y
) t ORDER BY 1, 2, 3, 4;

-- Q2
