package io.questdb.test.cairo.wal;

import io.questdb.PropertyKey;
import io.questdb.cairo.CairoException;
import io.questdb.cairo.ColumnType;
import io.questdb.cairo.PartitionBy;
import io.questdb.cairo.TableToken;
import io.questdb.cairo.TableUtils;
import io.questdb.cairo.TxReader;
import io.questdb.cairo.wal.WalUtils;
import io.questdb.std.Files;
import io.questdb.std.LongHashSet;
import io.questdb.std.str.LPSZ;
import io.questdb.std.str.Path;
import io.questdb.std.str.Utf8s;
import io.questdb.test.AbstractCairoTest;
import io.questdb.test.std.TestFilesFacadeImpl;
import org.junit.Assert;
import org.junit.Test;

/**
 * An apply job that ejects on its time quota or stops persists the WAL lag in _txn. The lag lives
 * in the last native partition's files after its rows. The next commit consumes it, and until that
 * commit writes _txn, the _txn on disk still points at those files. These tests stop the commit in
 * that window, by a process stop or by an msync failure, and restart from the files it leaves.
 */
public class WalLagCrashTest extends AbstractCairoTest {

    @Test
    public void testInPlaceAppendCrashKeepsPersistedLag() throws Exception {
        final LagWindowFilesFacade ff = new LagWindowFilesFacade();
        assertMemoryLeak(ff, () -> {
            final TableToken token = persistLagAfterEarlierRow(ff);

            // the second insert merges with the lag and appends in place into day 1, over the lag
            ff.armCrashImage();
            tickWalQueue(1);
            Assert.assertTrue("crash image was not taken", ff.isImageTaken());

            restartFromCrashImage(ff, token, 1_000);
            assertInPlaceAppendData();
        });
    }

    @Test
    public void testInPlaceAppendMsyncFailureKeepsPersistedLag() throws Exception {
        final LagWindowFilesFacade ff = new LagWindowFilesFacade();
        assertMemoryLeak(ff, () -> {
            setProperty(PropertyKey.CAIRO_COMMIT_MODE, "sync");
            final TableToken token = persistLagAfterEarlierRow(ff);

            // msync fails in commit00 after the in-place append and before the _txn write
            ff.armMsyncFailure();
            tickWalQueue(1);
            Assert.assertTrue("msync did not fail", ff.hasFailedMsync());
            Assert.assertTrue("the failed commit did not suspend the table", engine.getTableSequencerAPI().isSuspended(token));
            Assert.assertEquals("the failed commit wrote _txn", 1_000, persistedLagRowCount(token));

            execute("ALTER TABLE x RESUME WAL");
            drainWalQueue();
            Assert.assertFalse("re-apply suspended the table", engine.getTableSequencerAPI().isSuspended(token));
            assertInPlaceAppendData();
        });
    }

    @Test
    public void testLagAcrossPartitionBoundaryCrashKeepsPersistedLag() throws Exception {
        final LagWindowFilesFacade ff = new LagWindowFilesFacade();
        assertMemoryLeak(ff, () -> {
            // the apply job ejects after every transaction, and the ejection persists the WAL lag in _txn
            setProperty(PropertyKey.CAIRO_WAL_APPLY_TABLE_TIME_QUOTA, 0);
            execute("CREATE TABLE x (ts TIMESTAMP, a LONG) TIMESTAMP(ts) PARTITION BY DAY WAL WITH maxUncommittedRows=100");
            final TableToken token = engine.verifyTableName("x");
            ff.of(token);
            execute("INSERT INTO x VALUES ('2022-02-24', 1_000_000), ('2022-02-25', 2_000_000)");
            drainWalQueue();

            // the second insert sorts before the first, so the first insert's 2,000 rows, 600 on day 2
            // and 1,400 on day 3, go to WAL lag in day 2's files
            execute("INSERT INTO x SELECT timestamp_sequence('2022-02-25T23:50:00', 1_000_000L), x FROM long_sequence(2_000)");
            execute("INSERT INTO x VALUES ('2022-02-24T12:00:00', -1)");
            tickWalQueue(1);
            Assert.assertEquals("_txn does not persist the WAL lag", 2_000, persistedLagRowCount(token));

            // The second insert lands in day 1. The lag's day 2 rows append in place into day 2, and
            // the commit trims day 2 when the new day 3 becomes the last partition.
            ff.armCrashImage();
            tickWalQueue(1);
            Assert.assertTrue("crash image was not taken", ff.isImageTaken());

            restartFromCrashImage(ff, token, 2_000);
            assertQuery("SELECT count(), sum(a) FROM x")
                    .noLeakCheck()
                    .noRandomAccess()
                    .expectSize()
                    .returns("""
                            count\tsum
                            2003\t5000999
                            """);
            // the last lag rows sat beyond the trimmed page of day 2's files
            assertQuery("SELECT ts, a FROM x WHERE ts >= '2022-02-26T00:23:18'")
                    .noLeakCheck()
                    .timestamp("ts")
                    .returns("""
                            ts\ta
                            2022-02-26T00:23:18.000000Z\t1999
                            2022-02-26T00:23:19.000000Z\t2000
                            """);
        });
    }

    @Test
    public void testLagInNextPartitionCrashKeepsPersistedLag() throws Exception {
        // control: the commit leaves the lag region of day 1 untouched until _txn lands
        final LagWindowFilesFacade ff = new LagWindowFilesFacade();
        assertMemoryLeak(ff, () -> {
            setProperty(PropertyKey.CAIRO_WAL_APPLY_TABLE_TIME_QUOTA, 0);
            execute("CREATE TABLE x (ts TIMESTAMP, a LONG) TIMESTAMP(ts) PARTITION BY DAY WAL WITH maxUncommittedRows=50");
            final TableToken token = engine.verifyTableName("x");
            ff.of(token);
            execute("INSERT INTO x VALUES ('2022-02-25', 1_000_000)");
            drainWalQueue();

            execute("INSERT INTO x SELECT timestamp_sequence('2022-02-26T01:00:00', 1_000_000L), x FROM long_sequence(1_000)");
            execute("INSERT INTO x VALUES ('2022-02-26', -1)");
            tickWalQueue(1);
            Assert.assertEquals("_txn does not persist the WAL lag", 1_000, persistedLagRowCount(token));

            // the second insert merges the lag into a new native day 2
            ff.armCrashImage();
            tickWalQueue(1);
            Assert.assertTrue("crash image was not taken", ff.isImageTaken());

            restartFromCrashImage(ff, token, 1_000);
            assertQuery("SELECT count(), sum(a) FROM x")
                    .noLeakCheck()
                    .noRandomAccess()
                    .expectSize()
                    .returns("""
                            count\tsum
                            1002\t1500499
                            """);
            assertQuery("SELECT ts, a FROM x WHERE ts >= '2022-02-26T01:16:38'")
                    .noLeakCheck()
                    .timestamp("ts")
                    .returns("""
                            ts\ta
                            2022-02-26T01:16:38.000000Z\t999
                            2022-02-26T01:16:39.000000Z\t1000
                            """);
        });
    }

    private void assertInPlaceAppendData() throws Exception {
        assertQuery("SELECT count(), sum(a) FROM x")
                .noLeakCheck()
                .noRandomAccess()
                .expectSize()
                .returns("""
                        count\tsum
                        1002\t1500499
                        """);
        // the second insert's row appears once, and the last lag row survives
        assertQuery("SELECT ts, a FROM x WHERE a = -1 OR a = 1000")
                .noLeakCheck()
                .timestamp("ts")
                .returns("""
                        ts\ta
                        2022-02-25T00:30:00.000000Z\t-1
                        2022-02-25T01:16:39.000000Z\t1000
                        """);
    }

    // Day 1 holds one committed row. The second insert sorts before the first insert's 1,000 rows
    // but after day 1's row, so those rows go to WAL lag in day 1's files, and the ejected apply
    // job persists the lag in _txn.
    private static TableToken persistLagAfterEarlierRow(LagWindowFilesFacade ff) throws Exception {
        setProperty(PropertyKey.CAIRO_WAL_APPLY_TABLE_TIME_QUOTA, 0);
        execute("CREATE TABLE x (ts TIMESTAMP, a LONG) TIMESTAMP(ts) PARTITION BY DAY WAL WITH maxUncommittedRows=50");
        final TableToken token = engine.verifyTableName("x");
        ff.of(token);
        execute("INSERT INTO x VALUES ('2022-02-25', 1_000_000)");
        drainWalQueue();

        execute("INSERT INTO x SELECT timestamp_sequence('2022-02-25T01:00:00', 1_000_000L), x FROM long_sequence(1_000)");
        execute("INSERT INTO x VALUES ('2022-02-25T00:30:00', -1)");
        tickWalQueue(1);
        Assert.assertEquals("_txn does not persist the WAL lag", 1_000, persistedLagRowCount(token));
        return token;
    }

    private static int persistedLagRowCount(TableToken token) {
        try (TxReader txReader = new TxReader(engine.getConfiguration().getFilesFacade()); Path path = new Path()) {
            path.of(engine.getConfiguration().getDbRoot()).concat(token).concat(TableUtils.TXN_FILE_NAME);
            txReader.ofRO(path.$(), ColumnType.TIMESTAMP, PartitionBy.DAY);
            txReader.unsafeLoadAll();
            return txReader.getLagRowCount();
        }
    }

    private static void restartFromCrashImage(LagWindowFilesFacade ff, TableToken token, int lagRowCount) {
        // stop the process and restart it from the crash image
        releaseInactive(engine);
        ff.restoreImage();
        Assert.assertEquals("crash image must predate the _txn commit", lagRowCount, persistedLagRowCount(token));
        engine.notifyWalTxnCommitted(token);
        drainWalQueue();
        Assert.assertFalse("re-apply suspended the table", engine.getTableSequencerAPI().isSuspended(token));
    }

    /**
     * Stops a WAL apply commit between its data write and its _txn write. processWalCommit closes
     * the WAL segment column files of their last use in its finally block, after the data write and
     * before commit00 writes _txn; earlier uses detach their fds into a cache without closing them.
     * At the first such close after arming, the facade either copies the table directory aside,
     * which {@link #restoreImage()} later puts back, or arms a failure of the next msync, which
     * commit00 issues in sync commit mode before it writes _txn.
     */
    private static class LagWindowFilesFacade extends TestFilesFacadeImpl {
        private final LongHashSet walColumnFds = new LongHashSet();
        private String imageDir;
        private volatile boolean hasFailedMsync;
        private volatile boolean isArmed;
        private volatile boolean isImageTaken;
        private volatile boolean isMsyncFailureArmed;
        private boolean isMsyncFailureMode;
        private String tableDirName;
        private String walDirMarker;

        @Override
        public boolean close(long fd) {
            final boolean isWalColumn;
            synchronized (walColumnFds) {
                isWalColumn = walColumnFds.remove(fd) > -1;
            }
            if (isWalColumn && isArmed) {
                isArmed = false;
                if (isMsyncFailureMode) {
                    isMsyncFailureArmed = true;
                } else {
                    isImageTaken = takeImage();
                }
            }
            return super.close(fd);
        }

        @Override
        public void msync(long addr, long len, boolean async) {
            if (isMsyncFailureArmed) {
                isMsyncFailureArmed = false;
                hasFailedMsync = true;
                throw CairoException.critical(5).put("could not msync");
            }
            super.msync(addr, len, async);
        }

        @Override
        public long openRO(LPSZ name) {
            return trackWalColumn(name, super.openRO(name));
        }

        @Override
        public long openRONoCache(LPSZ name) {
            return trackWalColumn(name, super.openRONoCache(name));
        }

        void armCrashImage() {
            imageDir = temp.getRoot().getAbsolutePath() + Files.SEPARATOR + "crash_image";
            try (Path image = new Path()) {
                image.of(imageDir);
                if (exists(image.$())) {
                    Assert.assertTrue(rmdir(image));
                }
            }
            isMsyncFailureMode = false;
            isArmed = true;
        }

        void armMsyncFailure() {
            isMsyncFailureMode = true;
            isArmed = true;
        }

        boolean hasFailedMsync() {
            return hasFailedMsync;
        }

        boolean isImageTaken() {
            return isImageTaken;
        }

        void of(TableToken token) {
            tableDirName = token.getDirName();
            walDirMarker = tableDirName + Files.SEPARATOR + WalUtils.WAL_NAME_BASE;
        }

        void restoreImage() {
            try (Path table = new Path(); Path image = new Path()) {
                table.of(configuration.getDbRoot()).concat(tableDirName);
                image.of(imageDir);
                Assert.assertTrue(rmdir(table));
                Assert.assertEquals(0, copyRecursive(image, table, configuration.getMkDirMode()));
                Assert.assertTrue(rmdir(image));
            }
        }

        private boolean takeImage() {
            try (Path table = new Path(); Path image = new Path()) {
                table.of(configuration.getDbRoot()).concat(tableDirName);
                image.of(imageDir);
                return copyRecursive(table, image, configuration.getMkDirMode()) == 0;
            }
        }

        private long trackWalColumn(LPSZ name, long fd) {
            if (fd > -1 && walDirMarker != null && Utf8s.containsAscii(name, walDirMarker) && Utf8s.endsWithAscii(name, ".d")) {
                synchronized (walColumnFds) {
                    walColumnFds.add(fd);
                }
            }
            return fd;
        }
    }
}
