        }
        return String.format(
                "%-6s %-13s run %d: %5d ms total; page-release MS_SYNC msync: %4d calls, %5d ms; commit MS_SYNC msync: %3d calls, %4d ms; loadavg %s%n",
                mode, what, run, nanos / 1_000_000, pageReleaseSyncMsyncs, pageReleaseSyncMsyncNanos / 1_000_000,
                commitSyncMsyncs, commitSyncMsyncNanos / 1_000_000, load
        );
    }

    private static void reset() {
