body_text:
**Describe the bug**

The UDP line receiver writes into WAL tables through a plain table writer, outside the WAL. When a UDP line brings a new column, that writer adds the column to the table directly, and the WAL sequencer never learns about it. The next ordinary WAL write to the table, such as a SQL `INSERT`, cannot be applied, and the table is suspended. The insert's rows stay unapplied and the table takes no more writes until someone repairs it by hand. It happens whether the UDP line itself is accepted or rejected after the column was added, and in every commit mode (NOSYNC, ASYNC and SYNC).

**To reproduce**

1. Enable the UDP receiver (`line.udp.enabled=true`).
2. Create a WAL table with one row:
   ```sql
   CREATE TABLE x (ts TIMESTAMP, s SYMBOL, v LONG) TIMESTAMP(ts) PARTITION BY DAY WAL;
   INSERT INTO x VALUES ('2024-01-01', 'w', 0);
   ```
3. Send one line over UDP that has a new field `c`:
   ```
   x,s=u1 v=1i,c=5i 1704067201000000000
   ```
4. Insert a row with SQL:
   ```sql
   INSERT INTO x(ts, s, v) VALUES ('2024-01-01T00:00:02.000000Z', 'w2', 2);
   ```
5. `SELECT suspended FROM wal_tables() WHERE name = 'x';` returns `true`, and the row `w2` never appears.

<details><summary>Reproducer test</summary>

```java
// core/src/test/java/io/questdb/test/cutlass/line/udp/LineUdpWalColumnAddTest.java
package io.questdb.test.cutlass.line.udp;

import io.questdb.PropertyKey;
import io.questdb.cairo.CommitMode;
import io.questdb.cairo.TableToken;
import io.questdb.cutlass.line.udp.DefaultLineUdpReceiverConfiguration;
import io.questdb.cutlass.line.udp.LineUdpLexer;
import io.questdb.cutlass.line.udp.LineUdpParserImpl;
import io.questdb.std.MemoryTag;
import io.questdb.std.Unsafe;
import io.questdb.std.str.StringSink;
import io.questdb.test.AbstractCairoTest;
import org.junit.Assert;
import org.junit.Test;

import java.nio.charset.StandardCharsets;

// A UDP line that adds a column to a WAL table must not stop later WAL writes (a SQL INSERT) from being applied.
public class LineUdpWalColumnAddTest extends AbstractCairoTest {
    private static final String[] MODES = {"nosync", "async", "sync"};

    @Test
    public void testAcceptedLineAddsColumnThenSqlInsert() throws Exception {
        assertNotSuspended("acc", "%s,s=u1 v=1i,c=5i 1704067201000000000\n");
    }

    // The second line adds column c and is then rejected for a type mismatch on v.
    @Test
    public void testRejectedLineAddsColumnThenSqlInsert() throws Exception {
        assertNotSuspended("rej", "%s,s=u1 v=1i 1704067201000000000\n%s,s=u2 c=5i,v=\"x\" 1704067201000000000\n");
    }

    private static void assertNotSuspended(String label, String lineTemplate) throws Exception {
        assertMemoryLeak(() -> {
            final StringBuilder report = new StringBuilder();
            boolean ok = true;
            for (String mode : MODES) {
                setProperty(PropertyKey.CAIRO_COMMIT_MODE, mode);
                final int expectedMode = switch (mode) {
                    case "nosync" -> CommitMode.NOSYNC;
                    case "async" -> CommitMode.ASYNC;
                    default -> CommitMode.SYNC;
                };
                Assert.assertEquals(expectedMode, engine.getConfiguration().getCommitMode());
                final String table = label + "_" + mode;
                execute("create table " + table + " (ts timestamp, s symbol, v long) timestamp(ts) partition by day wal");
                execute("insert into " + table + " values ('2024-01-01', 'w', 0)");
                drainWalQueue();
                final TableToken token = engine.verifyTableName(table);
                try (
                        LineUdpParserImpl parser = new LineUdpParserImpl(engine, new DefaultLineUdpReceiverConfiguration());
                        LineUdpLexer lexer = new LineUdpLexer(4096)
                ) {
                    lexer.withParser(parser);
                    parse(lexer, lineTemplate.replace("%s", table));
                    lexer.parseLast();
                    parser.commitAll();
                }
                execute("insert into " + table + "(ts, s, v) values ('2024-01-01T00:00:02.000000Z', 'w2', 2)");
                drainWalQueue();
                final boolean suspended = engine.getTableSequencerAPI().isSuspended(token);
                report.append("mode=").append(mode).append(" suspended=").append(suspended).append('\n')
                        .append(print("select * from " + table)).append('\n');
                ok &= !suspended;
            }
            System.out.println("UDP-WAL-COLUMN-ADD " + label + "\n" + report);
            Assert.assertTrue(report.toString(), ok);
        });
    }

    private static void parse(LineUdpLexer lexer, String text) {
        final byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
        final long mem = Unsafe.malloc(bytes.length, MemoryTag.NATIVE_DEFAULT);
        try {
            for (int i = 0; i < bytes.length; i++) {
                Unsafe.putByte(mem + i, bytes[i]);
            }
            lexer.parse(mem, mem + bytes.length);
        } finally {
            Unsafe.free(mem, bytes.length, MemoryTag.NATIVE_DEFAULT);
        }
    }

    private static String print(String sql) throws Exception {
        final StringSink sink = new StringSink();
        engine.print(sql, sink);
        return sink.toString();
    }
}
