```diff
diff --git a/core/src/main/java/io/questdb/griffin/engine/functions/window/MultiPercentileContDoubleWindowFunctionFactory.java b/core/src/main/java/io/questdb/griffin/engine/functions/window/MultiPercentileContDoubleWindowFunctionFactory.java
index a1a33c71e6..b443ea622a 100644
--- a/core/src/main/java/io/questdb/griffin/engine/functions/window/MultiPercentileContDoubleWindowFunctionFactory.java
+++ b/core/src/main/java/io/questdb/griffin/engine/functions/window/MultiPercentileContDoubleWindowFunctionFactory.java
@@ -478,8 +478,15 @@ public class MultiPercentileContDoubleWindowFunctionFactory extends AbstractWind
             ArrayView percentiles = percentilesFunc.getArray(null);
             int percentileCount = SqlUtil.getPercentileCount(percentiles, percentilesPos);

-            // Sort the list
-            DoubleSort.sort(listMemory.getPageAddress(0), 0, size - 1);
+            int[] idx = new int[2 * percentileCount];
+            int n = 0;
+            for (int i = 0; i < percentileCount; i++) {
+                double position = SqlUtil.getPercentile(percentiles, i, percentilesPos) * (size - 1);
+                idx[n++] = (int) Math.floor(position);
+                idx[n++] = (int) Math.ceil(position);
+            }
+            java.util.Arrays.sort(idx, 0, n);
+            DoubleSort.quickSelectMultiple(listMemory.getPageAddress(0), 0, size - 1, idx, 0, n);

