import io.questdb.std.DoubleSort;
import io.questdb.std.MemoryTag;
import io.questdb.std.Rnd;
import io.questdb.std.Unsafe;
import io.questdb.std.Vect;
import io.questdb.std.str.StringSink;
import io.questdb.test.AbstractCairoTest;
import io.questdb.test.tools.TestUtils;
import org.junit.Assert;
import org.junit.Test;

import java.util.Arrays;

/**
 * Reproduces the cost of the full sort in the DOUBLE[] percentile window functions.
 * MultiPercentile{Disc,Cont}DoubleWindowFunctionFactory.preparePass2() sorts each
 * partition with DoubleSort.sort(), while the group-by DOUBLE[] forms select only the
 * requested order statistics with DoubleSort.quickSelectMultiple().
 */
public class PercentileWindowArraySortReproTest extends AbstractCairoTest {
    private static final int N = 4_000_000;
    private static final int RUNS = 7;

    @Test
    public void testSortVsQuickSelectMultiple() {
        final long bytes = 8L * N;
        final long src = Unsafe.malloc(bytes, MemoryTag.NATIVE_DEFAULT);
        final long a = Unsafe.malloc(bytes, MemoryTag.NATIVE_DEFAULT);
        final long b = Unsafe.malloc(bytes, MemoryTag.NATIVE_DEFAULT);
        try {
            final Rnd rnd = new Rnd();
            for (int i = 0; i < N; i++) {
                Unsafe.getUnsafe().putDouble(src + 8L * i, rnd.nextDouble());
            }
            // indices of percentile_disc(x, ARRAY[0.1, 0.5, 0.9]) over N values
            final int[] indices = {N / 10 - 1, N / 2 - 1, 9 * N / 10 - 1};

            final long[] sortNs = new long[RUNS];
            final long[] selectNs = new long[RUNS];
            for (int r = 0; r < RUNS; r++) {
                Vect.memcpy(a, src, bytes);
                Vect.memcpy(b, src, bytes);

                long t0 = System.nanoTime();
                DoubleSort.sort(a, 0, N - 1);
                sortNs[r] = System.nanoTime() - t0;

                t0 = System.nanoTime();
                DoubleSort.quickSelectMultiple(b, 0, N - 1, indices, 0, indices.length);
                selectNs[r] = System.nanoTime() - t0;

                for (int idx : indices) {
                    Assert.assertEquals(
                            Unsafe.getUnsafe().getDouble(a + 8L * idx),
                            Unsafe.getUnsafe().getDouble(b + 8L * idx),
                            0.0
                    );
                }
            }
            Arrays.sort(sortNs);
            Arrays.sort(selectNs);
            System.out.printf(
                    "REPRO %,d values: DoubleSort.sort median=%.1f ms, quickSelectMultiple(3) median=%.1f ms, ratio=%.1fx%n",
                    N, sortNs[RUNS / 2] / 1e6, selectNs[RUNS / 2] / 1e6, (double) sortNs[RUNS / 2] / selectNs[RUNS / 2]
            );
        } finally {
            Unsafe.free(src, bytes, MemoryTag.NATIVE_DEFAULT);
            Unsafe.free(a, bytes, MemoryTag.NATIVE_DEFAULT);
            Unsafe.free(b, bytes, MemoryTag.NATIVE_DEFAULT);
        }
    }

    @Test
    public void testWindowArrayFormTiming() throws Exception {
        assertMemoryLeak(() -> {
            execute("CREATE TABLE t AS (SELECT rnd_double() x FROM long_sequence(" + N + "))");
            final String[] queries = {
                    "SELECT percentile_disc(x, ARRAY[0.1, 0.5, 0.9]) OVER () p FROM t LIMIT 1",
                    "SELECT percentile_cont(x, ARRAY[0.1, 0.5, 0.9]) OVER () p FROM t LIMIT 1",
                    // group-by forms over the same data, which use quickSelectMultiple()
                    "SELECT percentile_disc(x, ARRAY[0.1, 0.5, 0.9]) p FROM t",
                    "SELECT percentile_cont(x, ARRAY[0.1, 0.5, 0.9]) p FROM t",
            };
            final StringSink sink = new StringSink();
            for (String q : queries) {
                final long[] ns = new long[RUNS];
                String result = null;
                for (int r = 0; r < RUNS; r++) {
                    sink.clear();
                    final long t0 = System.nanoTime();
                    TestUtils.printSql(engine, sqlExecutionContext, q, sink);
                    ns[r] = System.nanoTime() - t0;
                    if (result == null) {
                        result = sink.toString();
                    } else {
                        Assert.assertEquals(result, sink.toString());
                    }
                }
                Arrays.sort(ns);
                System.out.printf("REPRO %s -> median=%.1f ms, min=%.1f ms, result=%s%n",
                        q, ns[RUNS / 2] / 1e6, ns[0] / 1e6, result.replace('\n', ' '));
            }
        });
    }
}
```

