body_text:
An index scan on a `SYMBOL INDEX` column can return rows that do not belong to the key, or the same row twice, after a commit fails while the scan is running. The query does not fail.

The writer puts uncommitted rows into the index before the commit lands. If the commit fails, rollback frees those value blocks and the next writer zeroes or reuses them. A cursor that was already open still has the old value count and block pointers, so it walks into the freed block and returns its contents as rows of its key.

The per-key count check does not catch it: the count is not monotonic across rollback and re-add, and the writer stores the count before the last-block offset.

Red on master:

```java
package io.questdb.test.cairo;

import io.questdb.cairo.idx.BitmapIndexFwdReader;
import io.questdb.cairo.idx.BitmapIndexWriter;
import io.questdb.cairo.sql.RowCursor;
import io.questdb.std.LongList;
import io.questdb.std.str.Path;
import io.questdb.test.AbstractCairoTest;
import io.questdb.test.tools.TestUtils;
import org.junit.Assert;
import org.junit.Test;

import static io.questdb.cairo.TableUtils.COLUMN_NAME_TXN_NONE;

public class BitmapIndexRollbackReuseTest extends AbstractCairoTest {

    @Test
    public void testForwardCursorAfterRollbackAndWriterClose() throws Exception {
        TestUtils.assertMemoryLeak(() -> {
            try (Path path = new Path().of(configuration.getDbRoot())) {
                final int plen = path.size();
                BitmapIndexTest.create(configuration, path.trimTo(plen), "x", 2);
                try (
                        BitmapIndexWriter writer = new BitmapIndexWriter(configuration, path.trimTo(plen), "x", COLUMN_NAME_TXN_NONE);
                        BitmapIndexFwdReader reader = new BitmapIndexFwdReader(configuration, path.trimTo(plen), "x", COLUMN_NAME_TXN_NONE, -1, 0)
                ) {
                    // committed: rows 0..4, key 0 holds 0..3 (two blocks), key 1 holds 4
                    writer.add(0, 0);
                    writer.add(0, 1);
                    writer.add(0, 2);
                    writer.add(0, 3);
                    writer.add(1, 4);
                    writer.setMaxValue(4);
                    // index values for rows of a commit still in flight: key 0 gets a third block
                    writer.add(0, 5);
                    writer.add(0, 6);

                    // a query at the committed txn: rows 0..4 are visible
                    RowCursor cursor = reader.getCursor(0, 0, 4);
                    LongList rows = new LongList();
                    for (int i = 0; i < 3; i++) {
                        Assert.assertTrue(cursor.hasNext());
                        rows.add(cursor.next());
                    }

                    // the commit fails: rollback to the committed bound, writer is replaced
                    writer.rollbackValues(4);
                    writer.close();

                    while (cursor.hasNext()) {
                        rows.add(cursor.next());
                    }
                    Assert.assertEquals("[0,1,2,3]", rows.toString());
                }
            }
        });
    }
}
```

