use std::{iter::Iterator, sync::atomic::AtomicUsize};

#[derive(Clone, Copy)]
/// Our state, this type stores everything we need
/// to generate valid solutions to the problem. The
/// space complexity of this type is O(n) because
/// the size of each of the arrays in the type scale
/// linearly.
///
/// This is the most important type to keep *small*
/// since, we will be copying this type accross threads
/// ***a lot***
pub struct NQueensBoardJoyceLiu<const N: usize> {
    queen_locations: [u8; N],
    depth: usize,
    queen_state: i32,
    right_diagonals_occupied: i32,
    columns_occupied: i32,
    left_diagonals_occupied: i32,
    exclusion_mask: i32,
}

impl<const N: usize> NQueensBoardJoyceLiu<N> {
    const DONE: i32 = (1 << N) - 1;
    const EXCLUSION_MASK: i32 = (1 << (N / 2)) - 1;

    pub fn new() -> Self {
        Self {
            queen_locations: [0; N],
            queen_state: !Self::EXCLUSION_MASK & Self::DONE,
            right_diagonals_occupied: 0,
            columns_occupied: 0,
            left_diagonals_occupied: 0,
            exclusion_mask: if N % 2 == 1 { Self::EXCLUSION_MASK } else { 0 },
            depth: 0,
        }
    }
}

impl<const N: usize> Iterator for NQueensBoardJoyceLiu<N> {
    type Item = NQueensBoardJoyceLiu<N>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.queen_state == 0 {
            return None;
        }
        let new_queen_bit = self.queen_state & -self.queen_state;
        self.queen_state ^= new_queen_bit;
        self.queen_locations[self.depth] = new_queen_bit.trailing_zeros() as u8;

        let mut new_board = *self;
        new_board.right_diagonals_occupied |= new_queen_bit;
        new_board.right_diagonals_occupied >>= 1;
        new_board.columns_occupied |= new_queen_bit;
        new_board.left_diagonals_occupied |= new_queen_bit;
        new_board.left_diagonals_occupied <<= 1;
        new_board.depth += 1;
        new_board.queen_state = !(new_board.right_diagonals_occupied
            | new_board.left_diagonals_occupied
            | new_board.columns_occupied
            | new_board.exclusion_mask)
            & Self::DONE;
        new_board.exclusion_mask = 0;
        self.exclusion_mask = 0;
        Some(new_board)
    }
}

impl<const N: usize> ExactSizeIterator for NQueensBoardJoyceLiu<N> {
    fn len(&self) -> usize {
        self.queen_state.count_ones() as usize
    }
}

impl<const N: usize> DoubleEndedIterator for NQueensBoardJoyceLiu<N> {
    #[cold]
    fn next_back(&mut self) -> Option<Self::Item> {
        panic!();
    }
}

pub fn nqueens_joyce_liu_trampoline<const N: usize, I: Iterator<Item = NQueensBoardJoyceLiu<N>>>(
    board: NQueensBoardJoyceLiu<N>,
    solutions_found: &AtomicUsize,
    board_iter_creator: impl Fn(NQueensBoardJoyceLiu<N>) -> I + Send + Sync,
) {
    Iterator::for_each(Iterator::flatten(Iterator::flatten(board)), |board| {
        solutions_found.fetch_add(
            board_iter_creator(board).count() * 2,
            std::sync::atomic::Ordering::Relaxed,
        );
    });
}

fn main() {
    let solutions_found = AtomicUsize::new(0);
    nqueens_joyce_liu_trampoline(NQueensBoardJoyceLiu::<21>::new(), &solutions_found, |b| {
        Iterator::flatten(b)
            .flatten()
