onLineNumber:1,selectionStartColumn:1,selectionStartLineNumber:1,startColumn:1,startLineNumber:1),source:1),l:'5',n:'0',o:'+rustc+nightly',t:'0')),header:(),k:30.0,l:'4',n:'0',o:'',s:0,t:'0')),l:'2',n:'0',o:'',t:'0')),version:4)):

```rust
use std::ops::{BitAnd, BitAndAssign};

struct Foo([u128; 1]);

impl BitAndAssign<&Self> for Foo {
    #[unsafe(no_mangle)]
    fn bitand_assign(&mut self, other: &Self) {
        self.0[0] &= other.0[0];
    }
}

impl BitAnd<&Self> for Foo {
    type Output = Foo;
    #[unsafe(no_mangle)]
    fn bitand(mut self, other: &Self) -> Self::Output {
        self &= other;
        self
    }
}
```

