> struct W<T>(T);
> trait Blowup<T> {}
> impl<T> Blowup<()> for W<T> {}
> impl<T, U, V> Blowup<(T, U)> for W<V>
> where 
>     W<V>: Blowup<T>,
>     W<V>: Blowup<U>,    
> {}
> 
> trait Delay {
>     type Assoc;
> }
> 
> impl<T> Delay for W<T>
> where
>     W<T>: Blowup<T>
> {
>     type Assoc = T;
> }
> 
> fn bound<T: Delay<Assoc = ()>>() {}
> fn main() {
>     bound::<W<_>>();
> }
> ``` 

